import type { PersonProfileRecord, PersonRecord } from '../types/person';
import peopleCatalog from './people.json' with { type: 'json' };

type CatalogGapProfileSeed = Pick<
	PersonProfileRecord,
	'slug' | 'name' | 'headline' | 'roles' | 'birthPlace' | 'spotlight' | 'biography' | 'editorialBiography' | 'awards' | 'knownFor'
> & {
	sourceUrls?: string[];
	stats: NonNullable<PersonProfileRecord['stats']>;
};

const people = peopleCatalog as Record<string, PersonRecord>;

function optimizeProfileImage(person: PersonRecord): string {
	if (!person.remoteImageUrl) return person.image ?? '';
	if (person.remoteImageUrl.includes('commons.wikimedia.org')) {
		return person.remoteImageUrl.replace(/([?&]width=)\d+/u, '$1640');
	}
	return person.remoteImageUrl;
}

function buildCatalogGapProfile(seed: CatalogGapProfileSeed): PersonProfileRecord {
	const person = people[seed.name];
	if (!person?.image) throw new Error(`Falta el registro factual o el retrato local de ${seed.name}.`);

	const referenceUrls = Array.from(
		new Set([
			...(person.referenceUrls ?? []),
			...(person.imdbId ? [`https://www.imdb.com/name/${person.imdbId}/bio/`] : []),
			...(seed.sourceUrls ?? []),
		]),
	);

	return {
		slug: seed.slug,
		name: seed.name,
		profileImage: optimizeProfileImage(person),
		headline: seed.headline,
		roles: seed.roles,
		birthPlace: seed.birthPlace,
		spotlight: seed.spotlight,
		biography: seed.biography,
		editorialBiography: seed.editorialBiography,
		editorialStatus: 'approved',
		stats: seed.stats,
		awards: seed.awards,
		knownFor: seed.knownFor,
		referenceUrls,
	};
}

